import { securityQuestions } from './questions-security.js';

// Text is authored in the same pre-rotation order as questions-security.js.
// Metadata and answer indices come from the actual exported source questions.
// Apply the source module's rotation to both options and their explanations.
const q = (n, topic, stem, options, explanation, optionExplanations, takeaway) => {
  const original = securityQuestions.find(item => item.id === `sec-${String(n).padStart(3, '0')}`);
  if (!original || options.length !== original.options.length || optionExplanations.length !== options.length) {
    throw new Error(`Security translation does not match source question ${n}`);
  }
  const order = options.map((_, i) => (i + n % options.length) % options.length);
  return { ...original, topic, stem, options: order.map(i => options[i]), explanation,
    optionExplanations: order.map(i => optionExplanations[i]), takeaway };
};

